const m=e=>!!(e.userData&&(e.userData.isArm||e.userData.isLeg||e.userData.isHead))||e.name==="head";export function chestFront(e,{from:f=1,to:l=1.4,least:p=.11}={}){let i=p;const r=(t,u,h)=>{if(m(t))return;const[o,a]=[u+t.position.y,h+t.position.z],n=t.isMesh&&t.geometry&&t.geometry.attributes&&t.geometry.attributes.position;if(n)for(let s=0;s<n.count;s++){const c=n.getY(s)+o;c>=f&&c<=l&&(i=Math.max(i,n.getZ(s)+a))}for(const s of t.children||[])r(s,o,a)};for(const t of e.person&&e.person.children||[])r(t,0,0);return i}
